WITH ship_mode_stats AS (SELECT cs.cs_bill_hdemo_sk AS hd_sk, sm.sm_ship_mode_id, SUM(cs.cs_quantity) AS total_qty, SUM(cs.cs_net_paid) AS total_paid, ROW_NUMBER() OVER (PARTITION BY cs.cs_bill_hdemo_sk ORDER BY SUM(cs.cs_quantity) DESC) AS rn FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY cs.cs_bill_hdemo_sk, sm.sm_ship_mode_id), top_ship_mode AS (SELECT hd_sk, sm_ship_mode_id FROM ship_mode_stats WHERE rn = 1), cat_sales AS (SELECT cs.cs_bill_hdemo_sk AS hd_sk, SUM(cs.cs_quantity) AS cat_qty, SUM(cs.cs_net_paid) AS cat_net_paid, MAX(cs.cs_net_paid) AS max_cat_paid FROM catalog_sales cs GROUP BY cs.cs_bill_hdemo_sk), store_sales_agg AS (SELECT ss.ss_hdemo_sk AS hd_sk, SUM(ss.ss_quantity) AS store_qty, SUM(ss.ss_net_paid) AS store_net_paid, MAX(ss.ss_net_paid) AS max_store_paid FROM store_sales ss GROUP BY ss.ss_hdemo_sk) SELECT hd.hd_demo_sk, hd.hd_buy_potential, ts.sm_ship_mode_id AS top_ship_mode, COALESCE(cs.cat_qty, 0) AS cat_quantity, COALESCE(ss.store_qty, 0) AS store_quantity, (COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)) AS total_quantity, (COALESCE(cs.max_cat_paid, 0) + COALESCE(ss.max_store_paid, 0)) AS combined_max_paid, CASE WHEN (COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)) > 1500 THEN 'HIGH_VOLUME' ELSE 'NORMAL_VOLUME' END AS volume_flag, ROW_NUMBER() OVER (PARTITION BY hd.hd_buy_potential ORDER BY (COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)) DESC) AS row_num FROM household_demographics hd LEFT JOIN cat_sales cs ON hd.hd_demo_sk = cs.hd_sk LEFT JOIN store_sales_agg ss ON hd.hd_demo_sk = ss.hd_sk LEFT JOIN top_ship_mode ts ON hd.hd_demo_sk = ts.hd_sk WHERE hd.hd_vehicle_count > 2 ORDER BY row_num LIMIT 25
